export const Annotation: AnnotationFunction = function <
  ValueType,
  UpdateType = ValueType,
>(
  annotation?: SingleReducer<ValueType, UpdateType>
): BaseChannel<ValueType, OverwriteValue<ValueType> | UpdateType> {
  if (annotation) {
